-- Koperasi LPP Kedungneng: skema awal
-- Telah diterapkan ke proyek wlwfhelhaeiltnqfnzjd, 2026-10-27.
-- JANGAN jalankan ulang di proyek yang sudah memiliki tabel ini.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE public.pengaturan_koperasi(id smallint PRIMARY KEY DEFAULT 1 CHECK(id=1),nama text NOT NULL,simpanan_pokok_default numeric(18,2) NOT NULL CHECK(simpanan_pokok_default>=0),simpanan_wajib_bulanan numeric(18,2) NOT NULL CHECK(simpanan_wajib_bulanan>=0),bunga_flat_bulanan numeric(8,5) NOT NULL CHECK(bunga_flat_bulanan BETWEEN 0 AND 1),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.pengaturan_koperasi(id,nama,simpanan_pokok_default,simpanan_wajib_bulanan,bunga_flat_bulanan) VALUES(1,'Koperasi LPP Kedungneng',100000,10000,0.01);
CREATE TABLE public.anggota(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nomor_anggota text NOT NULL UNIQUE,nama_lengkap text NOT NULL,nomor_whatsapp text UNIQUE,tanggal_bergabung date NOT NULL DEFAULT current_date,status text NOT NULL DEFAULT 'aktif' CHECK(status IN('aktif','nonaktif')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.petugas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id),nama text NOT NULL,peran text NOT NULL CHECK(peran IN('admin','bendahara','petugas')),aktif boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.transaksi_simpanan(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nomor_bukti text NOT NULL UNIQUE,anggota_id uuid NOT NULL REFERENCES public.anggota(id),petugas_id uuid NOT NULL REFERENCES public.petugas(id),jenis text NOT NULL CHECK(jenis IN('pokok','wajib','sukarela')),arah text NOT NULL CHECK(arah IN('setor','tarik')),nominal numeric(18,2) NOT NULL CHECK(nominal>0),periode_wajib date,status text NOT NULL DEFAULT 'tercatat' CHECK(status IN('tercatat','dibatalkan')),keterangan text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(jenis<>'wajib' OR (arah='setor' AND periode_wajib IS NOT NULL)),CHECK(jenis='sukarela' OR arah='setor'));
CREATE UNIQUE INDEX simpanan_wajib_periode_unik ON public.transaksi_simpanan(anggota_id,periode_wajib) WHERE jenis='wajib' AND status='tercatat';
CREATE TABLE public.pengajuan_pinjaman(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),anggota_id uuid NOT NULL REFERENCES public.anggota(id),nominal numeric(18,2) NOT NULL CHECK(nominal>0),tenor_bulan integer NOT NULL CHECK(tenor_bulan>0),status text NOT NULL DEFAULT 'diajukan' CHECK(status IN('diajukan','disetujui','ditolak','dibatalkan')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.pinjaman(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nomor_pinjaman text NOT NULL UNIQUE,anggota_id uuid NOT NULL REFERENCES public.anggota(id),pengajuan_id uuid UNIQUE REFERENCES public.pengajuan_pinjaman(id),pokok_awal numeric(18,2) NOT NULL CHECK(pokok_awal>0),bunga_flat_bulanan numeric(8,5) NOT NULL CHECK(bunga_flat_bulanan BETWEEN 0 AND 1),tenor_bulan integer NOT NULL CHECK(tenor_bulan>0),tanggal_pencairan date NOT NULL,status text NOT NULL DEFAULT 'berjalan' CHECK(status IN('berjalan','lunas','dibatalkan')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.jadwal_angsuran(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pinjaman_id uuid NOT NULL REFERENCES public.pinjaman(id),angsuran_ke integer NOT NULL CHECK(angsuran_ke>0),jatuh_tempo date NOT NULL,pokok_tagihan numeric(18,2) NOT NULL CHECK(pokok_tagihan>=0),bunga_tagihan numeric(18,2) NOT NULL CHECK(bunga_tagihan>=0),UNIQUE(pinjaman_id,angsuran_ke));
CREATE TABLE public.pembayaran_angsuran(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nomor_bukti text NOT NULL UNIQUE,jadwal_angsuran_id uuid NOT NULL REFERENCES public.jadwal_angsuran(id),petugas_id uuid NOT NULL REFERENCES public.petugas(id),nominal_pokok numeric(18,2) NOT NULL CHECK(nominal_pokok>=0),nominal_bunga numeric(18,2) NOT NULL CHECK(nominal_bunga>=0),status text NOT NULL DEFAULT 'tercatat' CHECK(status IN('tercatat','dibatalkan')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(nominal_pokok+nominal_bunga>0));
CREATE TABLE public.transaksi_kas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nomor_bukti text NOT NULL UNIQUE,petugas_id uuid NOT NULL REFERENCES public.petugas(id),jenis text NOT NULL CHECK(jenis IN('penerimaan','pengeluaran','setor_ke_bendahara','terima_dari_petugas')),nominal numeric(18,2) NOT NULL CHECK(nominal>0),sumber_tipe text,sumber_id uuid,status text NOT NULL DEFAULT 'tercatat' CHECK(status IN('tercatat','dibatalkan')),keterangan text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.akun_akuntansi(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kode text NOT NULL UNIQUE,nama text NOT NULL,kategori text NOT NULL CHECK(kategori IN('aset','liabilitas','ekuitas','pendapatan','beban')));
CREATE TABLE public.jurnal(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nomor_jurnal text NOT NULL UNIQUE,tanggal date NOT NULL,keterangan text,sumber_tipe text,sumber_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.jurnal_detail(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),jurnal_id uuid NOT NULL REFERENCES public.jurnal(id),akun_id uuid NOT NULL REFERENCES public.akun_akuntansi(id),debit numeric(18,2) NOT NULL DEFAULT 0 CHECK(debit>=0),kredit numeric(18,2) NOT NULL DEFAULT 0 CHECK(kredit>=0),CHECK((debit>0 AND kredit=0) OR (kredit>0 AND debit=0)));
CREATE TABLE public.whatsapp_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),anggota_id uuid REFERENCES public.anggota(id),arah text NOT NULL CHECK(arah IN('masuk','keluar')),tipe_pesan text,status text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_user_id uuid,aksi text NOT NULL,nama_tabel text NOT NULL,record_id text,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['pengaturan_koperasi','anggota','petugas','transaksi_simpanan','pengajuan_pinjaman','pinjaman','jadwal_angsuran','pembayaran_angsuran','transaksi_kas','akun_akuntansi','jurnal','jurnal_detail','whatsapp_logs','audit_logs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;
COMMIT;
